import { ulid } from 'ulid';
import type { BusinessVaultDB } from '../db/database';
import type {
  ItemStock,
  JournalEntry,
  JournalLine,
  Purchase,
  PurchaseLine,
  StockMovement,
} from '../db/types';
import { appendSyncEvent } from './syncEventLog';
import { bankersRound, roundOffToNearestRupee } from './gst';
import { reconcileAfter } from './reconciliation';
import { log } from '../lib/log';
import { validateHsnSac } from './compliance';
import { addDaysYmd } from '../lib/date';

export interface PurchaseServiceDeps {
  db: BusinessVaultDB;
  now?: () => string;
}

export interface PurchaseLineInput {
  snapshotSource?: PurchaseLine['snapshot_source'];
  uqcCode?: string | null;
  goodsOrService?: PurchaseLine['goods_or_service'];
  taxability?: PurchaseLine['taxability'];
  itemId: string;
  description?: string;
  hsn?: string;
  warehouseId: string;
  qtyMicros: number;
  unitCostPaise: number;
  discountPaise?: number;
  taxRateBps: number;
  cessRateBps?: number;
  trackInventory?: boolean;
}

export interface CreatePurchaseInput {
  businessId: string;
  deviceId: string;
  billNumber: string;
  supplierBillNumber?: string;
  billDate: string;
  dueDate?: string | null;
  supplierId: string;
  supplierStateCode: string;
  isInterstate: boolean;
  financialYear: string;
  lines: PurchaseLineInput[];
  roundOffPaise?: number;
  roundOffMode?: 'auto' | 'none' | 'manual';
  notes?: string;
  attachmentId?: string | null;
  accounts: {
    purchases: string;
    inputCgst: string;
    inputSgst: string;
    inputIgst: string;
    inputCess: string;
    accountsPayable: string;
  };
  idempotencyKey?: string;
}

interface ComputedLine {
  line: PurchaseLine;
  movement: StockMovement | null;
}

function bpsMul(base: number, bps: number): number {
  // paise * bps / 10_000 with banker's (round-half-to-even) rounding to match
  // the codebase-wide money convention (see domain/gst.ts). Prior versions used
  // Math.round which rounds half-away-from-zero and produces a systematic bias
  // over long-running ledgers.
  return bankersRound((base * bps) / 10_000);
}

// Same guards as update(), worded for the UI so the Edit button / form can say
// why a bill is locked before the user retypes anything. update() re-checks on
// save (it also checks payment allocations, which need a query).
export function editBlockedReason(purchase: Purchase): string | null {
  if (purchase.status === 'cancelled') return 'This bill is cancelled and cannot be edited.';
  if (purchase.reversed_by_purchase_id) {
    return 'This bill has a purchase return. Cancel the debit note before editing the bill.';
  }
  if (purchase.paid_paise > 0) {
    return 'This bill has payments applied. Reverse the payments before editing the bill.';
  }
  return null;
}

export class PurchaseService {
  private readonly db: BusinessVaultDB;
  private readonly now: () => string;

  constructor(deps: PurchaseServiceDeps) {
    this.db = deps.db;
    this.now = deps.now ?? (() => new Date().toISOString());
  }

  async create(input: CreatePurchaseInput): Promise<Purchase> {
    if (!input.lines || input.lines.length === 0) {
      throw new Error('Purchase must have at least one line');
    }
    if (!input.billNumber || input.billNumber.trim().length === 0) {
      throw new Error('billNumber is required');
    }

    const now = this.now();
    const purchaseId = ulid();
    const journalId = ulid();

    let subtotal = 0;
    let discount = 0;
    let taxable = 0;
    let cgst = 0;
    let sgst = 0;
    let igst = 0;
    let cess = 0;
    const computed: ComputedLine[] = [];

    input.lines.forEach((li, idx) => {
      validateHsnSac(li.hsn, false, `Purchase line ${idx + 1}`);
      if (!Number.isInteger(li.qtyMicros) || li.qtyMicros <= 0) {
        throw new Error(`line[${idx}].qtyMicros must be positive integer`);
      }
      if (!Number.isInteger(li.unitCostPaise) || li.unitCostPaise < 0) {
        throw new Error(`line[${idx}].unitCostPaise must be non-negative integer paise`);
      }
      const lineDiscount = li.discountPaise ?? 0;
      // gross = qty (micros) * unitCost (paise per unit) / 1_000_000
      const gross = bankersRound((li.qtyMicros * li.unitCostPaise) / 1_000_000);
      const lineTaxable = gross - lineDiscount;
      if (lineTaxable < 0) {
        throw new Error(`line[${idx}].discountPaise exceeds line gross`);
      }
      const totalTax = bpsMul(lineTaxable, li.taxRateBps);
      const lineCgst = input.isInterstate ? 0 : bankersRound(totalTax / 2);
      const lineSgst = input.isInterstate ? 0 : totalTax - lineCgst;
      const lineIgst = input.isInterstate ? totalTax : 0;
      const lineCess = li.cessRateBps ? bpsMul(lineTaxable, li.cessRateBps) : 0;
      const lineTotal = lineTaxable + lineCgst + lineSgst + lineIgst + lineCess;

      subtotal += gross;
      discount += lineDiscount;
      taxable += lineTaxable;
      cgst += lineCgst;
      sgst += lineSgst;
      igst += lineIgst;
      cess += lineCess;

      const line: PurchaseLine = {
        id: ulid(),
        business_id: input.businessId,
        purchase_id: purchaseId,
        line_no: idx + 1,
        item_id: li.itemId,
        description: li.description ?? '',
        hsn: li.hsn ?? '',
        warehouse_id: li.warehouseId,
        qty_micros: li.qtyMicros,
        unit_cost_paise: li.unitCostPaise,
        discount_paise: lineDiscount,
        taxable_paise: lineTaxable,
        tax_rate_bps: li.taxRateBps,
        cgst_paise: lineCgst,
        sgst_paise: lineSgst,
        igst_paise: lineIgst,
        cess_paise: lineCess,
        line_total_paise: lineTotal,
      };

      let movement: StockMovement | null = null;
      if (li.trackInventory !== false) {
        movement = {
          id: ulid(),
          business_id: input.businessId,
          item_id: li.itemId,
          warehouse_id: li.warehouseId,
          movement_type: 'purchase',
          qty_micros: li.qtyMicros,
          unit_cost_paise: li.unitCostPaise,
          ref_type: 'purchase',
          ref_id: purchaseId,
          occurred_at: now,
          notes: `Purchase ${input.billNumber} line ${idx + 1}`,
        };
      }
      computed.push({ line, movement });
    });

    const preRoundTotal = taxable + cgst + sgst + igst + cess;
    let roundOff: number;
    let roundOffMode: 'auto' | 'none' | 'manual';
    if (input.roundOffMode === 'auto') {
      const auto = roundOffToNearestRupee(preRoundTotal);
      roundOff = auto.round_off_paise;
      roundOffMode = 'auto';
    } else if (input.roundOffMode === 'none') {
      roundOff = 0;
      roundOffMode = 'none';
    } else if (input.roundOffMode === 'manual') {
      roundOff = input.roundOffPaise ?? 0;
      roundOffMode = 'manual';
    } else {
      roundOff = input.roundOffPaise ?? 0;
      roundOffMode = roundOff === 0 ? 'none' : 'manual';
    }
    const total = preRoundTotal + roundOff;

    const dueDate = input.dueDate ?? addDaysYmd(input.billDate, 15);
    log.info('purchase', 'using purchase due date', {
      businessId: input.businessId,
      billNumber: input.billNumber.trim(),
      billDate: input.billDate,
      dueDate,
      defaulted: input.dueDate == null,
    });

    const purchase: Purchase = {
      id: purchaseId,
      business_id: input.businessId,
      bill_number: input.billNumber.trim(),
      supplier_bill_number: input.supplierBillNumber ?? '',
      bill_date: input.billDate,
      due_date: dueDate,
      supplier_id: input.supplierId,
      supplier_state_code: input.supplierStateCode,
      is_interstate: input.isInterstate ? 1 : 0,
      financial_year: input.financialYear,
      subtotal_paise: subtotal,
      discount_paise: discount,
      taxable_paise: taxable,
      cgst_paise: cgst,
      sgst_paise: sgst,
      igst_paise: igst,
      cess_paise: cess,
      round_off_paise: roundOff,
      round_off_mode: roundOffMode,
      pre_round_total_paise: preRoundTotal,
      total_paise: total,
      paid_paise: 0,
      balance_paise: total,
      status: 'received',
      reversed_by_purchase_id: null,
      reverses_purchase_id: null,
      replaces_purchase_id: null,
      replaced_by_purchase_id: null,
      reversal_journal_entry_id: null,
      cancelled_at: null,
      cancel_reason: null,
      notes: input.notes ?? '',
      attachment_id: input.attachmentId ?? null,
      journal_entry_id: journalId,
      created_at: now,
      updated_at: now,
      entity_version: 1,
    };

    // Double-entry journal: Dr Purchases + Dr Input GST(s), Cr Accounts Payable.
    const journalLines: JournalLine[] = [];
    let ln = 0;
    if (taxable > 0) {
      journalLines.push({
        id: ulid(),
        business_id: input.businessId,
        entry_id: journalId,
        line_no: ++ln,
        account_id: input.accounts.purchases,
        debit_paise: taxable,
        credit_paise: 0,
        party_type: 'supplier',
        party_id: input.supplierId,
        description: `Purchases from bill ${purchase.bill_number}`,
      });
    }
    if (cgst > 0) {
      journalLines.push({
        id: ulid(),
        business_id: input.businessId,
        entry_id: journalId,
        line_no: ++ln,
        account_id: input.accounts.inputCgst,
        debit_paise: cgst,
        credit_paise: 0,
        party_type: 'supplier',
        party_id: input.supplierId,
        description: 'Input CGST',
      });
    }
    if (sgst > 0) {
      journalLines.push({
        id: ulid(),
        business_id: input.businessId,
        entry_id: journalId,
        line_no: ++ln,
        account_id: input.accounts.inputSgst,
        debit_paise: sgst,
        credit_paise: 0,
        party_type: 'supplier',
        party_id: input.supplierId,
        description: 'Input SGST',
      });
    }
    if (igst > 0) {
      journalLines.push({
        id: ulid(),
        business_id: input.businessId,
        entry_id: journalId,
        line_no: ++ln,
        account_id: input.accounts.inputIgst,
        debit_paise: igst,
        credit_paise: 0,
        party_type: 'supplier',
        party_id: input.supplierId,
        description: 'Input IGST',
      });
    }
    if (cess > 0) {
      journalLines.push({
        id: ulid(),
        business_id: input.businessId,
        entry_id: journalId,
        line_no: ++ln,
        account_id: input.accounts.inputCess,
        debit_paise: cess,
        credit_paise: 0,
        party_type: 'supplier',
        party_id: input.supplierId,
        description: 'Input Cess',
      });
    }
    // Credit side: Accounts Payable for the total (net of round-off applied to debits? No —
    // round-off is a P&L bucket. Keep it simple: the AP credit is `total_paise` and we add
    // a matching round-off debit/credit line if roundOff != 0 to balance.
    journalLines.push({
      id: ulid(),
      business_id: input.businessId,
      entry_id: journalId,
      line_no: ++ln,
      account_id: input.accounts.accountsPayable,
      debit_paise: 0,
      credit_paise: total,
      party_type: 'supplier',
      party_id: input.supplierId,
      description: `Bill ${purchase.bill_number}`,
    });
    if (roundOff !== 0) {
      // roundOff was added to total; to keep debit = credit, add a matching debit
      // (if roundOff > 0) or credit (if roundOff < 0) to the purchases account.
      // Simpler: post the round-off on the purchases account itself.
      if (roundOff > 0) {
        journalLines.push({
          id: ulid(),
          business_id: input.businessId,
          entry_id: journalId,
          line_no: ++ln,
          account_id: input.accounts.purchases,
          debit_paise: roundOff,
          credit_paise: 0,
          party_type: 'supplier',
          party_id: input.supplierId,
          description: 'Round-off',
        });
      } else {
        journalLines.push({
          id: ulid(),
          business_id: input.businessId,
          entry_id: journalId,
          line_no: ++ln,
          account_id: input.accounts.purchases,
          debit_paise: 0,
          credit_paise: -roundOff,
          party_type: 'supplier',
          party_id: input.supplierId,
          description: 'Round-off',
        });
      }
    }

    let totalDebit = 0;
    let totalCredit = 0;
    for (const l of journalLines) {
      totalDebit += l.debit_paise;
      totalCredit += l.credit_paise;
    }
    if (totalDebit !== totalCredit) {
      throw new Error(
        `Purchase journal not balanced: debit=${totalDebit} credit=${totalCredit}`,
      );
    }

    const journal: JournalEntry = {
      id: journalId,
      business_id: input.businessId,
      entry_number: `JE-${purchase.bill_number}`,
      entry_date: purchase.bill_date,
      narration: `Purchase bill ${purchase.bill_number} from supplier ${input.supplierId}`,
      ref_type: 'purchase',
      ref_id: purchaseId,
      reversed_by_id: null,
      reverses_id: null,
      total_debit_paise: totalDebit,
      total_credit_paise: totalCredit,
      posted: 1,
      created_at: now,
      updated_at: now,
      entity_version: 1,
    };

    const db = this.db;

    return db.transaction(
      'rw',
      [
        db.purchases,
        db.purchase_lines,
        db.stock_movements,
        db.item_stock,
        db.items,
        db.units,
        db.journal_entries,
        db.journal_lines,
        db.sync_events,
      ],
      async () => {
        // Idempotency check FIRST: retries with the same idempotencyKey return
        // the previously-persisted purchase and skip re-mutation, so a retry
        // does not surface as a "Bill number already exists" error.
        if (input.idempotencyKey) {
          const priorEvents = (await db.sync_events.toArray()) as unknown as Array<
            Record<string, unknown>
          >;
          for (const r of priorEvents) {
            if (
              r['business_id'] === input.businessId &&
              r['entity_type'] === 'purchase' &&
              r['idempotency_key'] === input.idempotencyKey
            ) {
              const existing = await db.purchases.get(String(r['entity_id']));
              if (existing) return existing;
            }
          }
        }

        const dup = await db.purchases
          .where('[business_id+bill_number]')
          .equals([input.businessId, purchase.bill_number])
          .first();
        if (dup) {
          throw new Error(`Bill number already exists: ${purchase.bill_number}`);
        }

        await db.purchases.add(purchase);
        for (const c of computed) {
          const inputLine = input.lines[c.line.line_no - 1];
          const item = await db.items.get(c.line.item_id);
          const unit = item?.business_id === input.businessId ? await db.units.get(item.unit_id) : undefined;
          c.line.uqc_code = inputLine.uqcCode ?? (unit?.business_id === input.businessId ? unit.code : null);
          c.line.goods_or_service = inputLine.goodsOrService ?? (item?.business_id === input.businessId ? (item.is_service ? 'SERVICE' : 'GOODS') : null);
          c.line.taxability = inputLine.taxability ?? (c.line.tax_rate_bps > 0 ? 'TAXABLE' : null);
          c.line.cess_rate_bps = inputLine.cessRateBps ?? 0;
          c.line.snapshot_source = inputLine.snapshotSource ?? 'NATIVE';
          await db.purchase_lines.add(c.line);
        }

        for (const c of computed) {
          if (!c.movement) continue;
          await db.stock_movements.add(c.movement);
          const stockKey = `${input.businessId}:${c.movement.item_id}:${c.movement.warehouse_id}`;
          const existing = await db.item_stock.get(stockKey);
          if (existing) {
            // Moving-weighted-average cost: only recompute when the new stock
            // position is positive AND the incoming layer is positive. Negative
            // positions (backorders) are edge cases — preserve the old avg then.
            const oldQty = existing.qty_micros;
            const newQty = oldQty + c.movement.qty_micros;
            let newAvg = existing.avg_cost_paise;
            if (
              c.movement.qty_micros > 0 &&
              newQty > 0 &&
              (oldQty > 0 || existing.avg_cost_paise === 0)
            ) {
              // (oldQty * oldAvg + deltaQty * deltaCost) / newQty
              const totalValue =
                oldQty * existing.avg_cost_paise +
                c.movement.qty_micros * c.movement.unit_cost_paise;
              newAvg = Math.round(totalValue / newQty);
            }
            await db.item_stock.put({
              ...existing,
              qty_micros: newQty,
              avg_cost_paise: newAvg,
              updated_at: now,
            });
          } else {
            const row: ItemStock = {
              id: stockKey,
              business_id: input.businessId,
              item_id: c.movement.item_id,
              warehouse_id: c.movement.warehouse_id,
              qty_micros: c.movement.qty_micros,
              avg_cost_paise: c.movement.unit_cost_paise,
              updated_at: now,
            };
            await db.item_stock.add(row);
          }
        }

        await db.journal_entries.add(journal);
        for (const l of journalLines) await db.journal_lines.add(l);

        await appendSyncEvent(db, {
          businessId: input.businessId,
          deviceId: input.deviceId,
          entityType: 'purchase',
          entityId: purchase.id,
          operation: 'created',
          payload: purchase,
          timestamp: now,
          idempotencyKey: input.idempotencyKey,
        });
        for (const c of computed) {
          await appendSyncEvent(db, {
            businessId: input.businessId,
            deviceId: input.deviceId,
            entityType: 'purchase_line',
            entityId: c.line.id,
            operation: 'created',
            payload: c.line,
            timestamp: now,
          });
          if (c.movement) {
            await appendSyncEvent(db, {
              businessId: input.businessId,
              deviceId: input.deviceId,
              entityType: 'stock_movement',
              entityId: c.movement.id,
              operation: 'movement',
              payload: c.movement,
              timestamp: now,
            });
          }
        }
        await appendSyncEvent(db, {
          businessId: input.businessId,
          deviceId: input.deviceId,
          entityType: 'journal_entry',
          entityId: journal.id,
          operation: 'posted',
          payload: journal,
          timestamp: now,
        });
        for (const l of journalLines) {
          await appendSyncEvent(db, {
            businessId: input.businessId,
            deviceId: input.deviceId,
            entityType: 'journal_line',
            entityId: l.id,
            operation: 'created',
            payload: l,
            timestamp: now,
          });
        }

        return purchase;
      },
    );
  }

  // Internal mechanism used by update() to preserve the append-only journal
  // invariant during an edit: post a reversing JE + reverse stock movements and
  // flip the original's status to 'cancelled' with a renamed bill_number so the
  // number is free for the re-issued row. NOT user-facing — surface is Edit +
  // Delete (see update / delete flows).
  private async reversePurchasePosting(
    purchaseId: string,
    deviceId: string,
    reason: string,
  ): Promise<Purchase> {
    if (!reason || reason.trim().length === 0) {
      throw new Error('reversal reason required');
    }
    const original = await this.db.purchases.get(purchaseId);
    if (!original) throw new Error(`Purchase not found: ${purchaseId}`);
    if (original.status === 'cancelled') {
      throw new Error('Purchase already reversed');
    }

    const now = this.now();
    const reversalJournalId = ulid();

    const originalJournal = await this.db.journal_entries.get(original.journal_entry_id);
    if (!originalJournal) throw new Error('Original purchase journal missing');
    const originalJournalLines = await this.db.journal_lines
      .where('entry_id')
      .equals(original.journal_entry_id)
      .toArray();
    const originalMovements = await this.db.stock_movements
      .where('business_id')
      .equals(original.business_id)
      .filter((movement) => movement.ref_id === purchaseId)
      .toArray();

    const reversalLines: JournalLine[] = originalJournalLines.map((l, idx) => ({
      id: ulid(),
      business_id: l.business_id,
      entry_id: reversalJournalId,
      line_no: idx + 1,
      account_id: l.account_id,
      debit_paise: l.credit_paise,
      credit_paise: l.debit_paise,
      party_type: l.party_type,
      party_id: l.party_id,
      description: `Reversal: ${l.description}`,
    }));

    const reversalJournal: JournalEntry = {
      id: reversalJournalId,
      business_id: original.business_id,
      entry_number: `JE-REV-${original.bill_number}`,
      entry_date: original.bill_date,
      narration: `Reversal of purchase bill ${original.bill_number}: ${reason}`,
      ref_type: 'reversal',
      ref_id: purchaseId,
      reversed_by_id: null,
      reverses_id: original.journal_entry_id,
      total_debit_paise: originalJournal.total_credit_paise,
      total_credit_paise: originalJournal.total_debit_paise,
      posted: 1,
      created_at: now,
      updated_at: now,
      entity_version: 1,
    };

    const db = this.db;
    return db.transaction(
      'rw',
      [
        db.purchases,
        db.stock_movements,
        db.item_stock,
        db.journal_entries,
        db.journal_lines,
        db.sync_events,
      ],
      async () => {
        const reversalMovements: StockMovement[] = [];
        for (const m of originalMovements) {
          const reversalMovement: StockMovement = {
            id: ulid(),
            business_id: m.business_id,
            item_id: m.item_id,
            warehouse_id: m.warehouse_id,
            movement_type: 'adjustment',
            qty_micros: -m.qty_micros,
            unit_cost_paise: m.unit_cost_paise,
            ref_type: 'reversal',
            ref_id: reversalJournalId,
            occurred_at: now,
            notes: `Reversal of purchase ${original.bill_number}`,
          };
          reversalMovements.push(reversalMovement);
          await db.stock_movements.add(reversalMovement);
          const stockKey = `${m.business_id}:${m.item_id}:${m.warehouse_id}`;
          const stock = await db.item_stock.get(stockKey);
          if (stock) {
            await db.item_stock.put({
              ...stock,
              qty_micros: stock.qty_micros - m.qty_micros,
              updated_at: now,
            });
          }
        }

        await db.journal_entries.add(reversalJournal);
        for (const l of reversalLines) await db.journal_lines.add(l);
        await db.journal_entries.update(original.journal_entry_id, {
          reversed_by_id: reversalJournalId,
          updated_at: now,
        });

        // Rename the old bill_number so a re-create can reuse the number.
        // Append -REV-<ulid-suffix> to guarantee uniqueness. Append the reason
        // to notes so the trail is preserved.
        const reversedBillNumber = `${original.bill_number}-REV-${reversalJournalId.slice(-6)}`;
        const reversed: Purchase = {
          ...original,
          bill_number: reversedBillNumber,
          status: 'cancelled',
          notes: `${original.notes ? original.notes + '\n' : ''}[REVERSED ${now}] ${reason}`,
          reversal_journal_entry_id: reversalJournalId,
          cancelled_at: now,
          cancel_reason: reason,
          updated_at: now,
          entity_version: original.entity_version + 1,
        };
        await db.purchases.put(reversed);
        log.info('purchase.reversed', 'purchase posting reversed', {
          businessId: original.business_id,
          purchaseId: original.id,
          reason,
          reversalJournalId,
          totalPaise: original.total_paise,
        });

        await appendSyncEvent(db, {
          businessId: original.business_id,
          deviceId,
          entityType: 'purchase',
          entityId: purchaseId,
          operation: 'reversed',
          payload: {
            purchase_id: purchaseId,
            reason,
            reversal_journal_id: reversalJournalId,
            renamed_bill_number: reversedBillNumber,
          },
          timestamp: now,
        });
        await appendSyncEvent(db, {
          businessId: original.business_id,
          deviceId,
          entityType: 'journal_entry',
          entityId: reversalJournalId,
          operation: 'posted',
          payload: reversalJournal,
          timestamp: now,
        });
        for (const l of reversalLines) {
          await appendSyncEvent(db, {
            businessId: original.business_id,
            deviceId,
            entityType: 'journal_line',
            entityId: l.id,
            operation: 'created',
            payload: l,
            timestamp: now,
          });
        }
        for (const m of reversalMovements) {
          await appendSyncEvent(db, {
            businessId: original.business_id,
            deviceId,
            entityType: 'stock_movement',
            entityId: m.id,
            operation: 'movement',
            payload: m,
            timestamp: now,
          });
        }

        const updated = await db.purchases.get(purchaseId);
        return updated as Purchase;
      },
    );
  }

  /**
   * Edit an existing purchase. To preserve the append-only journal invariant,
   * the underlying implementation reverses the original's postings (journal +
   * stock) and posts a fresh purchase with the same bill_number. The reversed
   * original row stays cancelled + renamed for audit. Callers see a normal
   * "edit" — the reversal shape is not surfaced.
   */
  async update(
    purchaseId: string,
    input: Omit<CreatePurchaseInput, 'idempotencyKey'>,
  ): Promise<Purchase> {
    const db = this.db;
    log.info('purchase.edit', 'purchase edit started', { purchaseId, lineCount: input.lines.length });
    // One outer transaction so reverse + re-issue + link commit together. If
    // the corrected bill fails validation (bad HSN, zero qty, duplicate bill #)
    // the reversal rolls back and the original bill stays exactly as it was.
    const reissuedId = await db.transaction(
      'rw',
      [
        db.purchases,
        db.purchase_lines,
        db.stock_movements,
        db.item_stock,
        db.items,
        db.units,
        db.journal_entries,
        db.journal_lines,
        db.sync_events,
        db.payments,
      ],
      () => this.updateInTransaction(purchaseId, input),
    ).catch((e: unknown) => {
      log.info('purchase.edit', 'purchase edit rolled back', { purchaseId, error: String(e) });
      throw e;
    });
    // §17: reverse + reissue is a two-JE dance; verify TB net effect
    // equals the new bill and inventory identity holds.
    await reconcileAfter(input.businessId, 'purchase.recycle', { db });
    const reissued = await db.purchases.get(reissuedId);
    if (!reissued) throw new Error('Edited purchase missing after save');
    log.info('purchase.edit', 'purchase edit saved', {
      purchaseId,
      replacementId: reissued.id,
      totalPaise: reissued.total_paise,
    });
    return reissued;
  }

  private async updateInTransaction(
    purchaseId: string,
    input: Omit<CreatePurchaseInput, 'idempotencyKey'>,
  ): Promise<string> {
    const original = await this.db.purchases.get(purchaseId);
    if (!original) throw new Error(`Purchase not found: ${purchaseId}`);
    if (original.status === 'cancelled') {
      throw new Error('Cannot edit a cancelled purchase');
    }
    if (original.reversed_by_purchase_id) {
      throw new Error(
        'Cannot edit a bill that already has a purchase return; cancel the debit note first.',
      );
    }
    if (original.paid_paise > 0) {
      throw new Error('Cannot edit a bill with payments applied; reverse or migrate the payments first.');
    }
    const payments = await this.db.payments.where('business_id').equals(original.business_id).toArray();
    if (payments.some((payment) => payment.allocations.some((allocation) => allocation.bill_id === purchaseId))) {
      throw new Error('Cannot edit a bill referenced by a payment; reverse or migrate the payment first.');
    }
    const historicalLines = await this.db.purchase_lines.where('purchase_id').equals(purchaseId).toArray();
    const lines = input.lines.map((line, index) => {
      const old = historicalLines.find((row) => row.line_no === index + 1 && row.item_id === line.itemId);
      if (!old) return line;
      return { ...line, uqcCode: line.uqcCode ?? old.uqc_code, goodsOrService: line.goodsOrService ?? old.goods_or_service,
        taxability: line.taxability ?? old.taxability, cessRateBps: line.cessRateBps ?? old.cess_rate_bps ?? undefined,
        snapshotSource: old.snapshot_source === 'LEGACY_INFERRED' || !old.snapshot_source ||
          (old.uqc_code == null && line.uqcCode == null) ? 'LEGACY_INFERRED' as const : 'NATIVE' as const };
    });
    const reversed = await this.reversePurchasePosting(purchaseId, input.deviceId, 'edit');
    const reissued = await this.create({ ...input, lines });
    const now = this.now();
    await this.db.transaction('rw', [this.db.purchases, this.db.sync_events], async () => {
      const original = await this.db.purchases.get(purchaseId);
      const replacement = await this.db.purchases.get(reissued.id);
      if (!original || !replacement) throw new Error('Purchase replacement rows missing');
      await this.db.purchases.put({
        ...original,
        replaced_by_purchase_id: replacement.id,
        updated_at: now,
        entity_version: original.entity_version + 1,
      });
      await this.db.purchases.put({
        ...replacement,
        replaces_purchase_id: original.id,
        updated_at: now,
        entity_version: replacement.entity_version + 1,
      });
      await appendSyncEvent(this.db, {
        businessId: original.business_id,
        deviceId: input.deviceId,
        entityType: 'purchase',
        entityId: original.id,
        operation: 'updated',
        payload: {
          purchase_id: original.id,
          replaced_by_purchase_id: replacement.id,
          reversal_journal_entry_id: reversed.reversal_journal_entry_id,
        },
        timestamp: now,
      });
      await appendSyncEvent(this.db, {
        businessId: original.business_id,
        deviceId: input.deviceId,
        entityType: 'purchase',
        entityId: replacement.id,
        operation: 'updated',
        payload: { purchase_id: replacement.id, replaces_purchase_id: original.id },
        timestamp: now,
      });
    });
    return reissued.id;
  }

  async cancel(purchaseId: string, deviceId: string, reason = 'cancelled by user'): Promise<Purchase> {
    const purchase = await this.db.purchases.get(purchaseId);
    if (!purchase) throw new Error(`Purchase not found: ${purchaseId}`);
    if (purchase.status === 'cancelled') return purchase;
    if (purchase.reversed_by_purchase_id) {
      throw new Error(
        'Cannot cancel a bill that already has a purchase return; cancel the debit note instead.',
      );
    }
    if (purchase.paid_paise > 0) {
      throw new Error('Cannot cancel a bill with payments applied; reverse or migrate the payments first.');
    }
    const payments = await this.db.payments.where('business_id').equals(purchase.business_id).toArray();
    if (payments.some((payment) => payment.allocations.some((allocation) => allocation.bill_id === purchaseId))) {
      throw new Error('Cannot cancel a bill referenced by a payment.');
    }
    return this.reversePurchasePosting(purchaseId, deviceId, reason);
  }

  async delete(purchaseId: string, deviceId: string): Promise<Purchase> {
    return this.cancel(purchaseId, deviceId, 'deleted by user');
  }

  async get(id: string): Promise<Purchase | undefined> {
    return this.db.purchases.get(id);
  }

  async lines(purchaseId: string): Promise<PurchaseLine[]> {
    return this.db.purchase_lines
      .where('purchase_id')
      .equals(purchaseId)
      .toArray();
  }

  async list(businessId: string): Promise<Purchase[]> {
    return this.db.purchases
      .where('business_id')
      .equals(businessId)
      .toArray();
  }
}

export function createPurchaseService(
  deps: PurchaseServiceDeps,
): PurchaseService {
  return new PurchaseService(deps);
}
